package com.lootlookup;

import com.lootlookup.utils.Constants;
import com.lootlookup.views.GridRowOption;
import com.lootlookup.views.PriceType;
import com.lootlookup.views.ViewOption;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import java.awt.*;

import static com.lootlookup.utils.Constants.*;

@ConfigGroup(Constants.CONFIG_GROUP)
public interface LootLookupConfig extends Config {
    enum RightClickMenuOption {
        ALWAYS_SHOW,
        HOLD_SHIFT,
        DISABLE
    }

    @ConfigItem(
            position = 0,
            keyName = "defaultViewOption",
            name = "Default view option",
            description = "Select default view option"
    )
    default ViewOption viewOption() {
        return ViewOption.LIST;
    }

    @ConfigItem(
            position = 1,
            keyName = "showRarity",
            name = "Rarity",
            description = "Show/hide rarity for item"
    )
    default boolean showRarity() {
        return true;
    }

    @ConfigItem(
            position = 2,
            keyName = "showQuantity",
            name = "Quantity",
            description = "Show/hide quantity for item"
    )
    default boolean showQuantity() {
        return true;
    }

    @ConfigItem(
            position = 3,
            keyName = "showPrice",
            name = "Show Price",
            description = "Show/hide price for item"
    )
    default boolean showPrice() {
        return false;
    }

    @ConfigItem(
            position = 4,
            keyName = "priceType",
            name = "Price Type",
            description = "Select price type for item"
    )
    default PriceType priceType() {
        return PriceType.GE;
    }

    @ConfigItem(
            position = 5,
            keyName = "rightClickMenuOption",
            name = "Right click menu",
            description = "Control when the right-click menu option is shown for monsters"
    )
    default RightClickMenuOption rightClickMenuOption() {
        return RightClickMenuOption.ALWAYS_SHOW;
    }

    @ConfigItem(
            position = 6,
            keyName = "excludedMonsters",
            name = "Excluded monsters",
            description = "Comma-separated list of NPC names or IDs to hide the right-click menu option for. Names are matched case insensitive and must be singular (e.g. \"Dust devil\", not \"Dust devils\")."
    )
    default String excludedMonsters() {
        return "";
    }

    @ConfigItem(
            position = 7,
            keyName = "pinnedSubTables",
            name = "Pinned sections",
            description = "Comma-separated keywords to pin matching sections to the top of the drops panel (e.g. \"Tertiary\" pins Tertiary, Catacombs tertiary, etc.). Matched case-insensitively as substrings. Clear to keep sections in wiki order."
    )
    default String pinnedSubTables() {
        return "Unique, Tertiary";
    }

    @ConfigItem(
            position = 8,
            keyName = "disableItemLinks",
            name = "Disable Item links (List only)",
            description = "Disable links to OSRS Wiki page for item"
    )
    default boolean disableItemsLinks() {
        return false;
    }

    @ConfigItem(
            position = 9,
            keyName = "gridRowOption",
            name = "Items per row (Grid only)",
            description = "Number of items displayed in a grid row"
    )
    default GridRowOption gridRowOption() {
        return GridRowOption.FOUR;
    }

    @ConfigItem(
            position = 10,
            keyName = "commonColor",
            name = "Common Color",
            description = "Color to highlight the rarity of items with a value greater than 1/100"
    )
    default Color commonColor() {
        return DEFAULT_COMMON_COLOR;
    }

    @ConfigItem(
            position = 11,
            keyName = "rareColor",
            name = "Rare Color",
            description = "Color to highlight the rarity of items with a value of 1/100 - 1/1000"
    )
    default Color rareColor() {
        return DEFAULT_RARE_COLOR;
    }

    @ConfigItem(
            position = 12,
            keyName = "superRareColor",
            name = "Super Rare Color",
            description = "Color to highlight the rarity of items with a value of 1/1000 or less"
    )
    default Color superRareColor() {
        return DEFAULT_SUPER_RARE_COLOR;
    }

    @ConfigItem(
            position = 13,
            keyName = "priceColor",
            name = "Price Color",
            description = "Color to highlight item prices"
    )
    default Color priceColor() {
        return DEFAULT_PRICE_COLOR;
    }


}

package com.lootlookup;

import com.google.inject.Provides;

import javax.inject.Inject;
import javax.swing.*;
import java.util.Arrays;

import com.lootlookup.utils.Constants;
import com.lootlookup.utils.Icons;
import com.lootlookup.views.LootLookupPanel;
import net.runelite.api.*;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import okhttp3.OkHttpClient;

@PluginDescriptor(name = Constants.PLUGIN_NAME)
public class LootLookupPlugin extends Plugin {
    @Inject
    private Client client;
    @Inject
    private ClientToolbar clientToolbar;
    @Inject
    private LootLookupConfig config;
    @Inject
    private ConfigManager configManager;
    @Inject
    public OkHttpClient okHttpClient;

    private LootLookupPanel panel;
    private NavigationButton navButton;

    @Override
    protected void startUp() {
        migrateDisableMenuOption();

        panel = new LootLookupPanel(config, okHttpClient);

        navButton = NavigationButton.builder()
                .tooltip(Constants.PLUGIN_NAME)
                .icon(Icons.NAV_BUTTON)
                .priority(Constants.DEFAULT_PRIORITY)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);
    }

    @Override
    protected void shutDown() {
        clientToolbar.removeNavigation(navButton);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (event.getGroup().equals(Constants.CONFIG_GROUP)) {
            switch (event.getKey()) {
                case "showRarity":
                case "showQuantity":
                case "showPrice":
                case "priceType":
                case "disableItemLinks":
                case "commonColor":
                case "rareColor":
                case "superRareColor":
                case "priceColor":
                case "gridRowOption":
                    if (panel != null) {
                        panel.refreshMainPanel();
                    }
            }
        }
    }

    /**
     * Insert option adjacent to "Examine" when target is an attackable or
     * pickpocketable NPC.
     *
     * @param event
     */
    @Subscribe
    public void onMenuOpened(MenuOpened event) {
        // Bail before scanning the menu: under HOLD_SHIFT this is false for most
        // right-clicks, and the scan below does an NPC lookup per menu entry.
        if (!shouldShowRightClickMenuOption()) {
            return;
        }

        final var npcs = client.getTopLevelWorldView().npcs();
        MenuEntry[] menuEntries = event.getMenuEntries();

        boolean shouldShowLookup = false;
        String targetMonsterName = "";
        int combatLevel = 0;
        int monsterId = -1;

        for (MenuEntry menuEntry : menuEntries) {
            MenuAction menuType = menuEntry.getType();

            if (menuType == MenuAction.EXAMINE_NPC
                    || menuType == MenuAction.NPC_FIRST_OPTION
                    || menuType == MenuAction.NPC_SECOND_OPTION
                    || menuType == MenuAction.NPC_THIRD_OPTION
                    || menuType == MenuAction.NPC_FOURTH_OPTION
                    || menuType == MenuAction.NPC_FIFTH_OPTION) {
                String optionText = menuEntry.getOption();
                int id = menuEntry.getIdentifier();

                NPC target;
                try {
                    target = npcs.byIndex(id);
                } catch (ArrayIndexOutOfBoundsException ignored) {
                    continue;
                }

                if (target != null) {
                    combatLevel = target.getCombatLevel();
                    monsterId = target.getId();

                    boolean isAttack = optionText.equals("Attack") && combatLevel > 0;
                    boolean isPickpocket = optionText.equals("Pickpocket");
                    if (isAttack || isPickpocket) {
                        shouldShowLookup = true;
                        targetMonsterName = target.getName();
                    }
                }
            }
        }

        if (shouldShowLookup && !isMonsterExcluded(targetMonsterName, monsterId)) {
            MenuEntry entryToAppendOn = menuEntries[menuEntries.length - 1];

            int idx = Arrays.asList(menuEntries).indexOf(entryToAppendOn);

            String finalTargetMonsterName = targetMonsterName;
            int finalCombatLevel = combatLevel;
            int finalMonsterId = monsterId;

            client
                    .getMenu()
                    .createMenuEntry(idx - 1)
                    .setOption("Lookup Drops")
                    .setTarget(entryToAppendOn.getTarget())
                    .setIdentifier(entryToAppendOn.getIdentifier())
                    .setParam1(entryToAppendOn.getParam1())
                    .setType(MenuAction.of(MenuAction.RUNELITE.getId()))
                    .onClick(
                            evt -> {
                                selectNavButton();
                                panel.lookupMonsterDrops(finalTargetMonsterName, finalCombatLevel, finalMonsterId);
                            });
        }
    }

    /**
     * "disableMenuOption" (boolean) was replaced by "rightClickMenuOption" (enum) in 1.2.3 (#51).
     * Carry the old value over so users who had hidden the menu option keep it hidden.
     */
    private void migrateDisableMenuOption() {
        String legacy = configManager.getConfiguration(Constants.CONFIG_GROUP, "disableMenuOption");
        if (legacy == null) {
            return;
        }

        // RuneLite writes config defaults before startUp() runs, so "rightClickMenuOption"
        // is already set to ALWAYS_SHOW by now -- don't guard on it being absent. The legacy
        // key only survives a single upgrade, so its value wins here.
        configManager.setConfiguration(Constants.CONFIG_GROUP, "rightClickMenuOption",
                Boolean.parseBoolean(legacy)
                        ? LootLookupConfig.RightClickMenuOption.DISABLE
                        : LootLookupConfig.RightClickMenuOption.ALWAYS_SHOW);

        configManager.unsetConfiguration(Constants.CONFIG_GROUP, "disableMenuOption");
    }

    private boolean shouldShowRightClickMenuOption() {
        switch (config.rightClickMenuOption()) {
            case ALWAYS_SHOW:
                return true;
            case HOLD_SHIFT:
                return client.isKeyPressed(KeyCode.KC_SHIFT);
            case DISABLE:
            default:
                return false;
        }
    }

    private boolean isMonsterExcluded(String name, int id) {
        String excluded = config.excludedMonsters();
        if (excluded == null || excluded.trim().isEmpty()) {
            return false;
        }
        String idStr = String.valueOf(id);
        for (String entry : excluded.split(",")) {
            String trimmed = entry.trim();
            if (trimmed.isEmpty()) {
                continue;
            }
            if (trimmed.equalsIgnoreCase(name) || trimmed.equals(idStr)) {
                return true;
            }
        }
        return false;
    }

    @Provides
    LootLookupConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(LootLookupConfig.class);
    }

    public void selectNavButton() {
        SwingUtilities.invokeLater(
                () -> {
                    clientToolbar.openPanel(navButton);
                });
    }
}

package com.lootlookup.osrswiki;

import java.util.Map;

public class DropTableSection {
    private String header;
    private Map<String, WikiItem[]> table;

    public DropTableSection() {
    }

    public DropTableSection(String header, Map<String, WikiItem[]> table) {
        this.header = header;
        this.table = table;
    }

    public void setHeader(String newHeader) {
        this.header = newHeader;
    }

    public void setTable(Map<String, WikiItem[]> newTable) {
        this.table = newTable;
    }

    public String getHeader() {
        return header;
    }

    public Map<String, WikiItem[]> getTable() {
        return table;
    }
}

    package com.lootlookup.osrswiki;

import com.lootlookup.utils.Util;

import java.text.NumberFormat;


public class WikiItem {

    private String imageUrl;
    private String name;
    private int quantity;
    private String quantityStr;
    private String rarityStr;
    private double rarity;
    private int exchangePrice;
    private String exchangePriceStr;
    private int alchemyPrice;
    private String alchemyPriceStr;

    NumberFormat nf = NumberFormat.getNumberInstance();

    public WikiItem(String imageUrl, String name, int quantity, String quantityStr, String rarityStr, double rarity, int exchangePrice, String exchangePriceStr, int alchemyPrice, String alchemyPriceStr) {
        this.imageUrl = imageUrl;
        this.name = name;
        this.quantity = quantity;
        this.quantityStr = quantityStr;
        this.rarityStr = rarityStr;
        this.rarity = rarity;
        this.exchangePrice = exchangePrice;
        this.exchangePriceStr = exchangePriceStr;
        this.alchemyPrice = alchemyPrice;
        this.alchemyPriceStr = alchemyPriceStr;
    }

    public String getName() {
        return name;
    }

    public int getQuantity() {
        return quantity;
    }

    public String getQuantityStr() {
        return quantityStr;
    }

    public double getRarity() {
        return rarity;
    }

    public String getRarityStr() {
        return rarityStr;
    }
    public int getExchangePrice() {
        return exchangePrice;
    }
	public int getAlchemyPrice() {
		return alchemyPrice;
	}

    public String getImageUrl() {
        return imageUrl;
    }

    public boolean isNoted() {
        return quantityStr.endsWith(" (noted)");
    }

    public String getQuantityLabelText() {
        if (quantityStr.contains("-") || quantityStr.contains(";") || isNoted()) {
            return "x" + quantityStr;
        }
        return quantity > 0 ? "x" + nf.format(quantity) : quantityStr;
    }

    public String getQuantityLabelTextShort() {
        if (isNoted()) {
            return "x" + quantityStr.replaceAll("\\(.*\\)", "(n)").trim();
        }
        if (quantityStr.contains(";")) {
            return "x" + quantityStr;
        }
        return getQuantityValueText();
    }

    public String getQuantityValueText() {
        return quantity > 0 ? "x" + Util.rsFormat(quantity) : "";
    }

    public String getRarityLabelText(boolean percentMode) {
        String rarityLabelStr = rarityStr.contains(";") || rarityStr.equals("Always") || rarityStr.contains(" × ") ? rarityStr : Util.convertDecimalToFraction(rarity);
        if (percentMode) {
            rarityLabelStr = Util.toPercentage(rarity, rarity <= 0.0001 ? 3 : 2);
        }
        return rarityLabelStr;
    }

	public String getExchangePriceLabelText() {
		String priceLabelStr = exchangePrice > 0 ? nf.format(exchangePrice) + "gp" : "Not sold";
		if (name.equals("Nothing")) {
			priceLabelStr = "";
		}
		return priceLabelStr;
	}

	public String getExchangePriceLabelTextFull() {
		if (!name.equals("Nothing") && exchangePriceStr != null
				&& (exchangePriceStr.contains("-") || exchangePriceStr.contains(";"))) {
			return exchangePriceStr + "gp";
		}
		return getExchangePriceLabelText();
	}

	public String getExchangePriceLabelTextScaled() {
		if (exchangePrice <= 0 || name.equals("Nothing")) {
			return getExchangePriceLabelText();
		}
		return Util.rsScaledPrice(exchangePrice);
	}

	public String getExchangePriceLabelTextShort() {
		return getExchangePriceLabelTextScaled();
	}

	public String getAlchemyPriceLabelText() {
		String priceLabelStr = nf.format(alchemyPrice) + "gp";
		if (name.equals("Nothing") || alchemyPrice < 0) {
			priceLabelStr = "";
		}
		return priceLabelStr;
	}

	public String getAlchemyPriceLabelTextFull() {
		if (!name.equals("Nothing") && alchemyPrice >= 0 && alchemyPriceStr != null
				&& (alchemyPriceStr.contains("-") || alchemyPriceStr.contains(";"))) {
			return alchemyPriceStr + "gp";
		}
		return getAlchemyPriceLabelText();
	}

	public String getAlchemyPriceLabelTextScaled() {
		if (alchemyPrice < 0 || name.equals("Nothing")) {
			return getAlchemyPriceLabelText();
		}
		return Util.rsScaledPrice(alchemyPrice);
	}

	public String getAlchemyPriceLabelTextShort() {
		return getAlchemyPriceLabelTextScaled();
	}
}

package com.lootlookup.osrswiki;

import java.io.IOException;
import java.net.URI;
import java.net.URISyntaxException;
import java.text.NumberFormat;
import java.text.ParseException;
import java.util.*;
import java.util.concurrent.CompletableFuture;

import com.lootlookup.utils.Constants;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;

@Slf4j
public class WikiScraper {
    private final static String baseUrl = "https://oldschool.runescape.wiki";
    private final static URI baseUri = URI.create(baseUrl);
    private final static String wikiPagePath = "/w/";
    private final static String wikiLookupPath = wikiPagePath + "Special:Lookup";

    private static Document doc;

    public static CompletableFuture<DropTableSection[]> getDropsByMonster(OkHttpClient okHttpClient, String monsterName,
            int monsterId) {
        CompletableFuture<DropTableSection[]> future = new CompletableFuture<>();

        // Always resolve through Special:Lookup (even for a manual search with no
        // NPC id). Special:Lookup matches the name case-insensitively, whereas a
        // direct /w/ URL only auto-capitalizes the first letter. Newer multi-word
        // pages such as "Eldric the Ice King" have no lowercase redirect, so the
        // direct URL 404s while Special:Lookup still resolves them correctly.
        String url = getWikiUrlWithId(monsterName, monsterId);

        log.info("Looking up drops for monster: '{}' (ID: {}) at URL: {}", monsterName, monsterId, url);

        requestAsync(okHttpClient, url).whenCompleteAsync((responseHTML, ex) -> {
            List<DropTableSection> dropTableSections = new ArrayList<>();

            if (ex != null) {
                log.error("HTTP request failed for monster '{}': {}", monsterName, ex.getMessage(), ex);
                DropTableSection[] result = new DropTableSection[0];
                future.complete(result);
                return;
            }

            doc = Jsoup.parse(responseHTML);

            // Wiki structure: Headers are now direct h2/h3/h4 elements (no longer wrapped
            // in span.mw-headline)
            Elements tableHeaders = doc.select("h2, h3, h4");

            Boolean parseDropTableSection = false;
            DropTableSection currDropTableSection = new DropTableSection();
            Map<String, WikiItem[]> currDropTable = new LinkedHashMap<>();
            int tableIndexH3 = 0;
            int tableIndexH4 = 0;

            boolean incrementH3Index = false;

            for (Element tableHeader : tableHeaders) {
                String tableHeaderText = tableHeader.text();
                String monsterNameLC = monsterName.toLowerCase();

                // --- Handle edge cases for specific pages ---
                if (monsterNameLC.equals("hespori") && tableHeaderText.equals("Main table"))
                    continue;
                if (monsterNameLC.equals("chaos elemental") && tableHeaderText.equals("Major drops"))
                    continue;
                if (monsterNameLC.equals("cyclops") && tableHeaderText.equals("Drops"))
                    continue;
                if (monsterNameLC.equals("gorak") && tableHeaderText.equals("Drops"))
                    continue;
                if (monsterNameLC.equals("undead druid") && tableHeaderText.equals("Seeds")) {
                    incrementH3Index = true;
                    continue;
                }
                ;
                // ---

                String tableHeaderTextLower = tableHeaderText.toLowerCase();
                Boolean isDropsTableHeader = tableHeaderTextLower.contains("drop")
                        || tableHeaderTextLower.contains("levels")
                        || tableHeaderTextLower.contains("reward")
                        || tableHeaderTextLower.contains("pickpocket")
                        || tableHeaderTextLower.contains("hunter info")
                        || isDropsHeaderForEdgeCases(monsterName, tableHeaderText);
                Boolean isPickpocketLootHeader = tableHeaderTextLower.contains("loot");
                // An h3 whose heading is a variant "X drops" label (e.g.
                // "Wilderness Slayer Cave drops" on Jelly) is promoted to a
                // new primary drop table so its h4 children get a fresh map
                // and don't collide with an earlier variant's section keys.
                // Only promote once the current drop table already has
                // entries, so a leading h3 like Chaos Elemental's "Minor
                // drops" stays as a section of the parent h2.
                Boolean isSubDropsSection = tableHeaderTextLower.endsWith(" drops")
                        || tableHeaderTextLower.equals("drops");
                Boolean parseH3Primary = isPickpocketLootHeader
                        || (isSubDropsSection && !currDropTable.isEmpty())
                        || parseH3PrimaryForEdgeCases(monsterName);

                // Since we're selecting h2/h3/h4 directly now, check the element's tag name
                String tagName = tableHeader.tagName().toLowerCase();
                Boolean isParentH2 = tagName.equals("h2");
                Boolean isParentH3 = tagName.equals("h3");
                Boolean isParentH4 = tagName.equals("h4");

                // --- Handle edge cases for specific pages ---
                if (isParentH3 && tableHeaderText.equals("Regular drops")) {
                    incrementH3Index = true;
                    continue;
                }
                ;
                // ---

                if (isParentH2 || (parseH3Primary && isParentH3)) {
                    if (!currDropTable.isEmpty()) {
                        // reset section
                        currDropTableSection.setTable(currDropTable);
                        dropTableSections.add(currDropTableSection);

                        currDropTable = new LinkedHashMap<>();
                        currDropTableSection = new DropTableSection();
                    }

                    if (isDropsTableHeader || isPickpocketLootHeader) {
                        // new section
                        parseDropTableSection = true;
                        currDropTableSection.setHeader(tableHeaderText);

                        // Some pages (e.g. Elf (Thieving)) put a single flat
                        // item-drops table directly under the section heading
                        // with no h4 sub-headings. Look for one here so it
                        // doesn't get silently dropped.
                        Element directTable = findNextDropTable(tableHeader);
                        if (directTable != null) {
                            WikiItem[] directRows = getTableItemsFromElement(directTable);
                            if (directRows.length > 0 && !currDropTable.containsKey(tableHeaderText)) {
                                currDropTable.put(tableHeaderText, directRows);
                            }
                        }
                    } else {
                        parseDropTableSection = false;
                    }
                } else if (parseDropTableSection && (isParentH3 || isParentH4)) {
                    Element foundTable = findNextDropTable(tableHeader);

                    WikiItem[] tableRows = new WikiItem[0];
                    if (foundTable != null) {
                        tableRows = getTableItemsFromElement(foundTable);
                    }

                    if (tableRows.length > 0 && !currDropTable.containsKey(tableHeaderText)) {
                        currDropTable.put(tableHeaderText, tableRows);
                        if (isParentH4) {
                            tableIndexH4++;
                            if (incrementH3Index) {
                                tableIndexH3++;
                            }
                        } else {
                            tableIndexH3++;
                        }
                    }
                }
            }

            if (!currDropTable.isEmpty()) {
                currDropTableSection.setTable(currDropTable);
                dropTableSections.add(currDropTableSection);
            }

            if (dropTableSections.isEmpty()) {
                tableHeaders = doc.select("h2 span.mw-headline");

                if (!tableHeaders.isEmpty()) {
                    WikiItem[] tableRows = getTableItems(0, "h2 ~ table.item-drops");
                    if (tableRows.length > 0) {
                        currDropTable = new LinkedHashMap<>();
                        currDropTable.put("Drops", tableRows);
                        dropTableSections.add(new DropTableSection("Drops", currDropTable));
                    }
                }
            }

            DropTableSection[] result = dropTableSections.toArray(new DropTableSection[dropTableSections.size()]);

            if (result.length == 0) {
                log.warn(
                        "No drop tables found for monster '{}' (ID: {}). Check if the wiki page exists or has a different format.",
                        monsterName, monsterId);
            } else {
                log.info("Found {} drop table section(s) for monster '{}'", result.length, monsterName);
            }

            future.complete(result);
        });

        return future;
    }

    /**
     * Walks forward up to 5 siblings from a section heading looking for the
     * next {@code table.item-drops}. Stops when it hits another heading wrapper
     * so the search can't wander into a sibling section and mis-attribute
     * that section's table to the current heading.
     */
    private static Element findNextDropTable(Element tableHeader) {
        // Headers are wrapped in <div class="mw-heading mw-headingN">
        // We need to search from the wrapper div's siblings, not the header's siblings
        Element searchStart = tableHeader;
        Element parent = tableHeader.parent();
        if (parent != null && parent.hasClass("mw-heading")) {
            searchStart = parent;
        }

        Element searchElement = searchStart.nextElementSibling();
        int searchDepth = 0;
        while (searchElement != null && searchDepth < 5) {
            if (searchElement.hasClass("mw-heading")) {
                return null;
            }
            String tag = searchElement.tagName().toLowerCase();
            if (tag.equals("h2") || tag.equals("h3") || tag.equals("h4")) {
                return null;
            }

            if (tag.equals("table") && searchElement.hasClass("item-drops")) {
                return searchElement;
            }

            Elements tablesInside = searchElement.select("table.item-drops");
            if (!tablesInside.isEmpty()) {
                return tablesInside.first();
            }

            searchElement = searchElement.nextElementSibling();
            searchDepth++;
        }
        return null;
    }

    private static WikiItem[] getTableItems(int tableIndex, String selector) {
        List<WikiItem> wikiItems = new ArrayList<>();
        Elements dropTables = doc.select(selector);

        if (dropTables.size() > tableIndex) {
            Elements dropTableRows = dropTables.get(tableIndex).select("tbody tr");
            for (Element dropTableRow : dropTableRows) {
                String[] lootRow = new String[6];
                Elements dropTableCells = dropTableRow.select("td");
                int index = 1;

                for (Element dropTableCell : dropTableCells) {
                    String cellContent = dropTableCell.text();
                    Elements images = dropTableCell.select("img");

                    if (images.size() != 0) {
                        String imageSource = images.first().attr("src");
                        if (!imageSource.isEmpty()) {
                            lootRow[0] = baseUrl + imageSource;
                        }
                    }

                    if (cellContent != null && !cellContent.isEmpty() && index < 6) {
                        cellContent = filterTableContent(cellContent);
                        lootRow[index] = cellContent;
                        index++;
                    }
                }

                if (lootRow[0] != null) {
                    WikiItem wikiItem = parseRow(lootRow);
                    wikiItems.add(wikiItem);
                }
            }
        }

        WikiItem[] result = new WikiItem[wikiItems.size()];
        return wikiItems.toArray(result);
    }

    private static WikiItem[] getTableItemsFromElement(Element table) {
        List<WikiItem> wikiItems = new ArrayList<>();
        Elements dropTableRows = table.select("tbody tr");

        for (Element dropTableRow : dropTableRows) {
            String[] lootRow = new String[6];
            Elements dropTableCells = dropTableRow.select("td");
            int index = 1;

            for (Element dropTableCell : dropTableCells) {
                String cellContent = dropTableCell.text();
                Elements images = dropTableCell.select("img");

                if (images.size() != 0) {
                    String imageSource = images.first().attr("src");
                    if (!imageSource.isEmpty()) {
                        lootRow[0] = baseUrl + imageSource;
                    }
                }

                if (cellContent != null && !cellContent.isEmpty() && index < 6) {
                    cellContent = filterTableContent(cellContent);
                    lootRow[index] = cellContent;
                    index++;
                }
            }

            if (lootRow[0] != null) {
                WikiItem wikiItem = parseRow(lootRow);
                wikiItems.add(wikiItem);
            }
        }

        WikiItem[] result = new WikiItem[wikiItems.size()];
        return wikiItems.toArray(result);
    }

    public static WikiItem parseRow(String[] row) {
        String imageUrl = "";
        String name = "";

        double rarity = -1;
        String rarityStr = "";

        int quantity = 0;
        String quantityStr = "";
        int exchangePrice = -1;
        String exchangePriceStr = null;
        int alchemyPrice = -1;
        String alchemyPriceStr = null;

        if (row.length > 4) {
            imageUrl = row[0];
            name = row[1];
            if (name.endsWith("(m)")) {
                // (m) indicates members only, remove because it's not part of actual item name
                name = name.substring(0, name.length() - 3);
            }

            NumberFormat nf = NumberFormat.getNumberInstance();

            quantityStr = row[2];
            quantityStr = quantityStr.replaceAll("–", "-").replace('\u00A0', ' ').trim();
            try {
                String[] quantityStrs = quantityStr.replaceAll("\\s+", "").split("[-;]");
                String firstQuantityStr = quantityStrs.length > 0 ? quantityStrs[0] : null;
                quantity = nf.parse(firstQuantityStr).intValue();
            } catch (ParseException e) {
            }

            rarityStr = row[3];
            if (rarityStr.startsWith("~")) {
                rarityStr = rarityStr.substring(1);
            } else if (rarityStr.startsWith("2 × ") || rarityStr.startsWith("3 × ")) {
                rarityStr = rarityStr.substring(4);
            }

            try {
                String[] rarityStrs = rarityStr.replaceAll("\\s+", "").split(";");
                String firstRarityStr = rarityStrs.length > 0 ? rarityStrs[0] : null;

                if (firstRarityStr != null) {
                    if (firstRarityStr.equals("Always")) {
                        rarity = 1.0;
                    } else {
                        String[] fraction = firstRarityStr.split("/");
                        if (fraction.length > 1) {
                            double numer = nf.parse(fraction[0]).doubleValue();
                            double denom = nf.parse(fraction[1]).doubleValue();
                            rarity = numer / denom;
                        }

                    }
                }
            } catch (ParseException ex) {
            }

            if (row[4] != null) {
                exchangePriceStr = row[4].replaceAll("–", "-").replace('\u00A0', ' ').trim();
            }
            try {
                exchangePrice = nf.parse(row[4]).intValue();
            } catch (ParseException ex) {
            }
            if (row[5] != null) {
                alchemyPriceStr = row[5].replaceAll("–", "-").replace('\u00A0', ' ').trim();
            }
            try {
                alchemyPrice = nf.parse(row[5]).intValue();
            } catch (ParseException ex) {
            }
        }
        return new WikiItem(imageUrl, name, quantity, quantityStr, rarityStr, rarity, exchangePrice, exchangePriceStr, alchemyPrice, alchemyPriceStr);
    }

    public static String filterTableContent(String cellContent) {
        return cellContent.replaceAll("\\[.*\\]", "");
    }

    public static String getWikiUrl(String itemOrMonsterName) {
        String sanitizedName = sanitizeName(itemOrMonsterName);
        return buildWikiUrl(wikiPagePath + sanitizedName, null, null);
    }

    public static String getWikiUrlWithId(String monsterName, int id) {
        return getWikiUrlWithId(monsterName, id, null);
    }

    private static String getWikiUrlWithId(String monsterName, int id, String fragment) {
        String sanitizedName = sanitizeName(monsterName);
        // --- Handle edge cases for specific pages ---
        if (id == 7851 || id == 7852) {
            // Redirect Dusk and Dawn to Grotesque Guardians page
            id = -1;
            sanitizedName = "Grotesque_Guardians";
        }
        // When sanitizeName has rewritten the monster name to a different target page,
        // zero the NPC id so Special:Lookup resolves by the rewritten name rather than
        // the original NPC, matching the Dusk/Dawn pattern above.
        String monsterNameLC = monsterName.toLowerCase();
        if (monsterNameLC.equals("blood moon") || monsterNameLC.equals("blue moon")
                || monsterNameLC.equals("eclipse moon")) {
            id = -1;
        }
        // ---
        return buildWikiUrl(wikiLookupPath, "type=npc&id=" + id + "&name=" + sanitizedName, fragment);
    }

    public static String getWikiUrlForDrops(String monsterName, String anchorText, int monsterId) {
        if (monsterId > -1) {
            return getWikiUrlWithId(monsterName, monsterId);
        }
        String anchorStr = "Drops";
        if (anchorText != null) {
            anchorStr = anchorText.replaceAll("\\s+", "_");
        }
        // No NPC id (manual search): resolve through Special:Lookup, which matches
        // the name case-insensitively. A direct /w/ URL only auto-capitalizes the
        // first letter, so multi-word pages like "Eldric the Ice King" 404. The
        // browser carries the #section fragment across the redirect to the page.
        return getWikiUrlWithId(monsterName, monsterId, anchorStr);
    }

    /**
     * Assembles a wiki URL via the multi-argument URI constructor, which percent-encodes
     * any character that is illegal in its component (for example the double quotes in
     * Gorak's "Full" Gorak drop table section header) while leaving legal characters such
     * as underscores, apostrophes, parentheses and the query separators untouched.
     * LinkBrowser.browse validates its argument with URI.create and throws on a malformed
     * URL, so everything handed to it must already be well-formed.
     */
    private static String buildWikiUrl(String path, String query, String fragment) {
        try {
            return new URI(baseUri.getScheme(), baseUri.getHost(), path, query, fragment).toASCIIString();
        } catch (URISyntaxException e) {
            // Only reachable if the constant scheme or host above were malformed.
            throw new IllegalStateException("Could not build wiki URL for path " + path, e);
        }
    }

    public static String sanitizeName(String name) {
        // --- Handle edge cases for specific pages ---
        if (name.equalsIgnoreCase("tzhaar-mej")) {
            name = "tzhaar-mej (monster)";
        }
        if (name.equalsIgnoreCase("dusk") || name.equalsIgnoreCase("dawn")) {
            name = "grotesque guardians";
        }
        // Moons of Peril: individual boss pages have no drop tables; loot lives on Lunar Chest
        if (name.equalsIgnoreCase("blood moon") || name.equalsIgnoreCase("blue moon")
                || name.equalsIgnoreCase("eclipse moon")) {
            name = "lunar chest";
        }
        // DT2: Awakened variants don't have separate wiki pages; they share the base boss page
        if (name.toLowerCase().matches("^awakened\\s+(vardorvis|duke sucellus|(the\\s+)?leviathan|(the\\s+)?whisperer)$")) {
            name = name.replaceAll("(?i)^awakened\\s+", "");
        }
        // ---
        name = name.trim().toLowerCase().replaceAll("\\s+", "_");
        return name.substring(0, 1).toUpperCase() + name.substring(1);
    }

    public static Boolean isDropsHeaderForEdgeCases(String monsterName, String tableHeaderText) {
        String monsterNameLC = monsterName.toLowerCase();
        String tableHeaderTextLower = tableHeaderText.toLowerCase();
        return (monsterNameLC.equals("cyclops") && (tableHeaderTextLower.contains("warriors' guild") ||
                tableHeaderText.equals("Ardougne Zoo")))
                || (monsterNameLC.equals("vampyre juvinate") &&
                        tableHeaderTextLower.equals("returning a juvinate to human"));
    }

    public static Boolean parseH3PrimaryForEdgeCases(String monsterName) {
        String monsterNameLC = monsterName.toLowerCase();
        return monsterNameLC.equals("cyclops");
    }

    private static CompletableFuture<String> requestAsync(OkHttpClient okHttpClient, String url) {
        CompletableFuture<String> future = new CompletableFuture<>();

        Request request = new Request.Builder().url(url).header("User-Agent", Constants.USER_AGENT).build();

        okHttpClient
                .newCall(request)
                .enqueue(
                        new Callback() {
                            @Override
                            public void onFailure(Call call, IOException ex) {
                                log.error("HTTP call failed for URL '{}': {}", url, ex.getMessage(), ex);
                                future.completeExceptionally(ex);
                            }

                            @Override
                            public void onResponse(Call call, Response response) throws IOException {
                                try (ResponseBody responseBody = response.body()) {
                                    if (!response.isSuccessful()) {
                                        log.warn("HTTP request unsuccessful. Status code: {} for URL: {}",
                                                response.code(), url);
                                        future.complete("");
                                        return;
                                    }

                                    log.debug("HTTP request successful (status {})", response.code());
                                    future.complete(responseBody.string());
                                } finally {
                                    response.close();
                                }
                            }
                        });

        return future;
    }

}

